/* edit a receipt or a waste / use entry: the old one is voided (kind «edit») and a new one replaces it */
function editForm(kind,id){const doc=raw().inventory,r=kind==='receipt'?A(doc.stockReceipts).find(x=>x.id===id):W.findEvent(doc,id);if(!r)return;const i=M().ing.get(r.ingredientId||r.itemId),mn=r.type==='menu'?M().menu.get(r.itemId):null,units=i&&!mn?W.unitsOf(i):[{name:'عدد',factor:1}],qty=r.entryQuantity??r.quantity,un=r.entryUnit||units[0].name;
 const types=Object.entries(W.EVENT_LABELS).filter(([k])=>k!=='FRYER_OIL_CHANGE'&&(W.AUTH_TYPES.has(k)===W.AUTH_TYPES.has(r.eventType)));
 formModal({title:kind==='receipt'?'ویرایش ورود انبار':'ویرایش پرتی / مصرف',onMount:m=>bindSection(m),ok:'ذخیره روی سرور',body:`<div class="sum-box"><span>${esc((mn||i)?.name||r.itemNameSnapshot||'—')}</span><b>${fa(r.date)}</b></div>
  <div class="form-grid">${P.field('تاریخ',`<input class="input num" name="date" value="${fa(r.date)}">`)}${kind==='receipt'?'':P.field('نوع رویداد',`<select class="select" name="type">${types.map(([k,l])=>`<option value="${k}" ${k===r.eventType?'selected':''}>${esc(l)}</option>`).join('')}</select>`)}</div>
  <div class="iw-qty">${P.field(mn?'تعداد':'مقدار',`<input class="input num" name="qty" value="${fa(qty)}" inputmode="decimal">`)}${P.field('واحد',`<select class="select" name="unit">${units.map(u=>`<option ${u.name===un?'selected':''}>${esc(u.name)}</option>`).join('')}</select>`)}${kind==='receipt'?'':P.field('شیفت',`<select class="select" name="shift">${W.SHIFTS.map(s=>`<option ${s===r.shift?'selected':''}>${s}</option>`).join('')}</select>`)}</div>
  ${kind==='receipt'?P.field('توضیح',`<input class="input" name="note" value="${esc(r.notes||'')}">`):P.field('علت',`<input class="input" name="reason" value="${esc(r.reason||'')}">`)+P.field('توضیح',`<textarea class="textarea" name="notes" rows="2">${esc(r.notes||'')}</textarea>`)+sectionFields(recSection(r),r.responsiblePersonnelId||'')}
  ${P.field('علت ویرایش',`<input class="input" name="why" placeholder="مثلاً مقدار اشتباه وارد شده بود">`)}${P.note('ثبت قبلی حذف نمی‌شود: «باطل (ویرایش‌شده)» می‌ماند و ثبت تازه جای آن را می‌گیرد؛ مغایرت شمارش‌های بعدی خودکار بازمحاسبه می‌شود.','info')}`,
  onSave:(m,btn)=>{if(!canVoid())throw Error('ویرایش فقط برای کاربر دارای دسترسی «ویرایش، ابطال و بازگردانی ثبت‌های انبار» مجاز است');const date=E.D(val(m,'date')),why=val(m,'why');
   if(kind==='receipt')return run(btn,{action:'RECEIPT_EDITED',details:{entityId:id},mutate:(d,c)=>W.editReceipt(d,c,{id,date,quantity:val(m,'qty'),unit:val(m,'unit'),note:val(m,'note'),reason:why}),done:()=>'ورود ویرایش شد'});
   run(btn,{negWarn:true,action:'INVENTORY_EVENT_EDITED',details:{entityId:id},mutate:(d,c)=>W.editEvent(d,c,{id,date,eventType:val(m,'type'),quantity:val(m,'qty'),unit:val(m,'unit'),shift:val(m,'shift'),reason:val(m,'reason'),notes:val(m,'notes'),...sectionInput(m)}),done:()=>'ثبت ویرایش شد'})}})}
/* ---------- «نقطهٔ سفارش» as a board (APP_REVIEW P-12) ----------
   Items with a reorder point, grouped by supplier (the item's supplier in the tracking settings, else its primary
   supplier in «تأمین‌کنندگان ← اقلام», else the preferred supplier of the old mirror suppliers.items, else the supplier of its latest invoice): a bar of today's computed stock against the target with a mark at the reorder
   point; «نیاز به سفارش» = at or under the reorder point, «نزدیک» = up to 30٪ above it. A reorder point of 0 counts as not set. Suggested order = target − stock,
   also in purchase units with the last purchase price. «کپی متن سفارش» copies a message per supplier; no SMS in this phase. */
let roF='need';
function roRows(){const sup=window.FinanceReal?.suppliers?.(),sups=A(sup?.suppliers),byCode=new Map(sups.map(x=>[x.code,x])),rel=new Map;
 for(const r of A(sup?.supplierItems))if(r.ingredientId&&(r.isPrimary||!rel.has(r.ingredientId)))rel.set(r.ingredientId,byCode.get(r.supplierCode));
 /* the preferred supplier of the item in the old supplier mirror (suppliers.items, by item code) when no relation is set */const pref=new Map(A(sup?.items).filter(x=>x.code&&x.preferredSupplierCode).map(x=>[String(x.code),byCode.get(x.preferredSupplierCode)]));for(const i of M().ing.values())if(!rel.get(i.id)&&pref.get(String(i.code)))rel.set(i.id,pref.get(String(i.code)));
 /* else the supplier of the latest final invoice that had the item */const last=new Map;for(const x of A(IC.state.raw?.inventory?.purchaseInvoices).filter(x=>window.PurchaseWrite?.isFinal?.(x)&&x.supplierId).sort((a,b)=>String(a.date).localeCompare(String(b.date))))for(const l of A(x.lines))last.set(l.ingredientId,x.supplierId);for(const [id,sid] of last)if(!rel.get(id)){const s1=sups.find(x=>x.id===sid);if(s1)rel.set(id,s1)}
 return pos().filter(r=>r.hasReorderPoint&&r.reorderPoint>0).map(r=>{const i=M().ing.get(r.id)||{},q0=r.qty??0,st=q0<=r.reorderPoint?'need':q0<=r.reorderPoint*1.3?'near':'ok',sug=Math.max(0,r.target-q0),pk=Number(i.packageQuantity)>0?Number(i.packageQuantity):1,packs=Math.ceil(sug/pk-1e-9);
  const s0=sups.find(x=>x.id===r.supplierId)||rel.get(r.id)||null;return{...r,st,sug,packs,pu:i.purchaseUnit||r.unit,cost:packs*(Number(i.lastPurchasePriceToman)||0),sup:s0}})}
function reorderReal(){const FR=window.FinanceReal;if(!FR?.suppliers?.()&&!FR?.supState?.err)FR?.loadSuppliers?.();const all=roRows(),cnt=k=>all.filter(r=>r.st===k).length,noRp=pos().filter(r=>!(r.hasReorderPoint&&r.reorderPoint>0)).length;
 const rows=all.filter(r=>roF==='all'||r.st===roF||(roF==='near'&&r.st==='need')).sort((a,b)=>(a.qty??0)/a.reorderPoint-(b.qty??0)/b.reorderPoint),groups=new Map;
 for(const r of rows){const k=r.sup?.id||'';if(!groups.has(k))groups.set(k,{sup:r.sup,rows:[]});groups.get(k).rows.push(r)}
 const bar=r=>{const max=Math.max(r.target,r.reorderPoint,r.qty??0)||1,w=Math.max(0,Math.min(100,(r.qty??0)/max*100));return`<div class="ro-bar ${r.st==='need'?((r.qty??0)<=0?'out':'low'):''}" title="موجودی ${q(r.qty)} · نقطهٔ سفارش ${q(r.reorderPoint)} · هدف ${q(r.target)}"><i style="width:${w}%"></i><b style="inset-inline-start:${r.reorderPoint/max*100}%"></b></div>`};
 const card=g=>{const name=g.sup?(g.sup.company||g.sup.contactName):'بدون تأمین‌کننده',cost=g.rows.reduce((a,r)=>a+(r.st!=='ok'?r.cost:0),0);
  return P.card({cls:'ro-sup',title:`${esc(name)} <small class="muted">${fa(g.rows.length)} قلم</small>`,sub:[g.sup?.mobile||g.sup?.phone,g.sup?.orderDays&&'روز سفارش: '+g.sup.orderDays].filter(Boolean).map(esc).join(' · '),actions:`${cost?`<span class="muted" style="font-size:12px">برآورد ${P.mt(Math.round(cost))} ${P.U()}</span>`:''}<button class="btn btn-sm" data-rocopy="${esc(g.sup?.id||'')}">${P.ic('copy')}کپی متن سفارش</button>`,flush:1,
   body:P.table(['کالا','',{t:'موجودی',n:1},{t:'نقطهٔ سفارش',n:1},{t:'هدف',n:1},{t:'پیشنهاد سفارش',n:1,noSum:1},'وضعیت'],g.rows.map(r=>[esc(r.name),bar(r),`${q(r.qty)} <small class="muted">${esc(r.unit)}</small>`,q(r.reorderPoint),q(r.target),r.st==='ok'?'—':`<b>${fa(r.packs)} ${esc(r.pu)}</b>${r.pu!==r.unit?` <small class="muted">(${q(r.sug)} ${esc(r.unit)})</small>`:''}`,r.st==='need'?P.b('نیاز به سفارش','danger',1):r.st==='near'?P.b('نزدیک','warning',1):P.b('کافی','success',1)]),{cls:'no-grid'})})};
 return srcLine()+salesGap()+`<div class="row" style="gap:8px;flex-wrap:wrap;margin-bottom:var(--s4)">${P.chips('ro',[['need','نیاز به سفارش',cnt('need')],['near','نیاز + نزدیک',cnt('need')+cnt('near')],['all','همه',all.length]],roF)}</div>`
  +(canWrite()?`<div class="row" style="margin-bottom:var(--s3)"><button class="btn btn-sm" id="roSug">${P.ic('wand-sparkles')}پیشنهاد نقطهٔ سفارش از مصرف</button></div>`:'')+(groups.size?[...groups.values()].sort((a,b)=>(a.sup?0:1)-(b.sup?0:1)||b.rows.length-a.rows.length).map(card).join('<div class="mt"></div>'):P.note(roF==='need'?'هیچ قلمی زیر نقطهٔ سفارش نیست.':'موردی نیست.','check'))
  +`<div class="mt">${P.note(`موجودی از محاسبهٔ انبار (آخرین شمارش + ورود − مصرف) است؛ تا فروش و شمارش کامل نشده، پیشنهادها تقریبی‌اند. ${fa(noRp)} قلم نقطهٔ سفارش ندارند؛ در «تنظیمات انبار» تعریف کنید.`,'info')}</div>`}
function reorderMount(root){P.bindChips(root,'ro',k=>{roF=k;P.render()});const sg=P.$('#roSug',root);if(sg)sg.onclick=reorderSuggest;(P.$('#pnTab',root)||root).onclick=async e=>{const b=e.target.closest('[data-rocopy]');if(!b)return;const id=b.dataset.rocopy,rs=roRows().filter(r=>(r.sup?.id||'')===id&&r.st!=='ok');if(!rs.length)return P.toast('قلمی برای سفارش نیست','info');
 const name=rs[0].sup?(rs[0].sup.contactName||rs[0].sup.company):'',txt=[`سلام${name?' '+name:''}، سفارش رایو برای ${E.CAL.today}:`,...rs.map(r=>`- ${r.name}: ${r.packs} ${r.pu}`),'ممنون'].map(P.fa).join('\n');
 try{await navigator.clipboard.writeText(txt);P.toast('متن سفارش کپی شد','check')}catch(_){P.modal({title:'متن سفارش',body:`<pre class="night-text">${esc(txt)}</pre>`})}}}
/* ---------- «ایرادهای داده» as a work list (APP_REVIEW P-16) ----------
   The issues of the inventory analysis of the dashboard period (InvControl, by default the current month), one row each
   with the button that fixes it. The count of the first visit of the month is kept in this browser to show progress. */
const ISS={salesGap:['danger','روزهای بی‌فروش','ورود فایل فروش',()=>P.go('#/inventory/sales')],noRecipe:['danger','فروش بی‌رسپی','تعریف رسپی',i=>openRecipe(i)],badRecipe:['danger','رسپی نامعتبر','اصلاح رسپی',i=>openRecipe(i)],
 suspectWaste:['danger','پرتی با احتمال خطای واحد','اصلاح ثبت',i=>editForm('event',i.ref)],suspectReceipt:['danger','ورود با مقدار غیرعادی','اصلاح ورود',i=>editForm('receipt',i.ref)],negative:['danger','موجودی منفی','گردش قلم',i=>ledger(i.item)],
 pair:['warning','جفت کسری و مازاد هم‌اندازه','گردش قلم',i=>ledger(i.item)],suspectPrice:['warning','قیمت مشکوک','اصلاح قلم',i=>window.CatalogReal?.ingredientForm?.(i.item)],unapproved:['warning','شمارش تأییدنشده','انبارگردانی',()=>P.go('#/inventory/count')],
 countUnit:['warning','واحد شمارش ناسازگار','اصلاح قلم',i=>window.CatalogReal?.ingredientForm?.(i.item)],receiptUnit:['warning','واحد ورود ناسازگار','اصلاح ورود',i=>editForm('receipt',i.ref)],noOpen:['warning','بدون شمارش اول دوره','شمارش',i=>countForm({only:[i.item],title:'شمارش «'+i.name+'»'})],
 staffAsWaste:['info','غذای پرسنل به‌عنوان پرتی','',null],notCounted:['info','در پایان دوره شمرده نشده','شمارش',i=>countForm({only:[i.item],title:'شمارش «'+i.name+'»'})],openShift:['info','شمارش اول با فاصله','',null]};
function openRecipe(i){const m=[...M().menu.values()].find(x=>(i.code&&String(x.code)===String(i.code))||x.name===i.name);if(m&&window.MenuEntry?.recipe)MenuEntry.recipe(m.id);else P.go('#/menu/recipes')}
const issDetail=i=>({salesGap:`${fa(i.covered)} از ${fa(i.days)} روز فروش دارد`,noRecipe:`${q(i.qty)} فروش · ${T(i.amount)} ${P.U()}`,badRecipe:esc(i.detail||''),suspectWaste:`${fa(i.date)} · ${q(i.qty,3)} ${esc(i.unit)} (شاید ${q(i.fix,3)})`,suspectReceipt:`${fa(i.date)} · ${q(i.qty,3)} ${esc(i.unit)} (شاید ${q(i.fix,3)})`,negative:`${q(i.expected,3)} ${esc(i.unit)}`,pair:`با «${esc(i.other)}»`,suspectPrice:`بهای دوره ${T(i.cost)} · کاتالوگ ${T(i.catalog)}`,countUnit:`${esc(i.countUnit||'')} به‌جای ${esc(i.unit)}`,receiptUnit:`${fa(i.date)} · ${esc(i.unit)} به‌جای ${esc(i.expectedUnit)}`,staffAsWaste:`${q(i.qty,3)}`}[i.type]||'');
let isF='danger',isList=[];
function issuesReal(){const Pp=IC.state.P;if(!Pp)return srcLine()+P.note('تحلیل انبار هنوز آماده نیست.','loader');const per=IC.period(),all=A(Pp.issues).filter(i=>ISS[i.type]),sev=t=>ISS[t]?.[0],n=k=>all.filter(i=>sev(i.type)===k).length,key='rayo.issues.'+(per.month||per.from);
 let base=0;try{base=Number(localStorage.getItem(key))||0;if(!base||all.length>base){base=Math.max(base,all.length);localStorage.setItem(key,String(base))}}catch(_){}
 isList=all.filter(i=>isF==='all'||sev(i.type)===isF).sort((a,b)=>Object.keys(ISS).indexOf(a.type)-Object.keys(ISS).indexOf(b.type)||Math.abs(b.impact||b.amount||0)-Math.abs(a.impact||a.amount||0));const done=base?Math.max(0,base-all.length):0;
 return srcLine()+`<div class="grid grid-4">${P.kpi({label:'ایرادهای باز',icon:'list-checks',value:fa(all.length),foot:`${per.month?E.monthLabel(per.month):fa(per.from)+' تا '+fa(per.to)} · دورهٔ داشبورد کنترل`})}${P.kpi({label:'جدی',icon:'alert-octagon',value:fa(n('danger')),tone:n('danger')?'danger':'',foot:'تا رفع نشوند مغایرت قابل استناد نیست'})}${P.kpi({label:'هشدار',icon:'alert-triangle',value:fa(n('warning')),foot:'دقت را کم می‌کنند'})}${P.kpi({label:'رفع‌شده از اول ماه',icon:'check',value:fa(done),foot:base?`از ${fa(base)} ایراد`:''})}</div>
  <div class="row mt" style="gap:8px;flex-wrap:wrap">${P.chips('iss',[['danger','جدی',n('danger')],['warning','هشدار',n('warning')],['info','اطلاع',n('info')],['all','همه',all.length]],isF)}</div>
  <div class="mt">${P.card({flush:1,body:P.table(['نوع','مورد','جزئیات',{t:'',noSort:1}],isList.slice(0,300).map((i,k)=>[P.b(ISS[i.type][1],ISS[i.type][0]==='info'?'neutral':ISS[i.type][0],1),esc(i.name||(i.type==='salesGap'?'فروش':'—')),issDetail(i),ISS[i.type][3]?`<button class="btn btn-sm" data-isfix="${k}">${ISS[i.type][2]}</button>`:'']),{empty:'ایرادی در این دسته نیست 🎉'})})}</div>
  ${P.note('دوره را در «داشبورد کنترل» عوض کنید. بعد از هر اصلاح، فهرست با دادهٔ تازه دوباره ساخته می‌شود.','info')}`}
function issuesMount(root){P.bindChips(root,'iss',k=>{isF=k;P.render()});(P.$('#pnTab',root)||root).onclick=e=>{const b=e.target.closest('[data-isfix]');if(!b)return;const i=isList[+b.dataset.isfix];try{ISS[i.type][3](i)}catch(x){P.toast(x.message||String(x),'alert-triangle')}}}

/* ---------- «شمارش امروز»: cycle counting by ABC (APP_REVIEW P-08) ---------- */
let cyF='ab';
const parkedSet=()=>E.parkedIds(raw().inventory,raw().pricing);
function cycleData(){const inv=raw().inventory,set=W.cycleSettings(inv),t=E.CAL.today;let a=null;try{a=E.analyze(M(),E.CAL.k(E.CAL.i(t)-59),t)}catch(_){}
 const items=stockList(),val=new Map(A(a?.items).map(r=>[r.id,(r.salesV||0)+(r.wasteV||0)+(r.staffV||0)])),cls=W.abcClasses(items.map(i=>({id:i.id,value:val.get(i.id)||0})),set);
 const act=new Map(A(a?.items).map(r=>[r.id,Math.max((r.salesV||0)+(r.wasteV||0)+(r.staffV||0),r.receiptV||0)]));
 const rows=W.cycleDue(items.map(i=>i.id),cls,W.lastCountDates(inv),set,t).map(r=>({...r,i:M().ing.get(r.id),value:val.get(r.id)||0,activity:act.get(r.id)||0}));return{set,rows}}
/* «شمارش امروز»: class C items whose 60-day use value is under 0.2% of the total and not parked yet → suggestion to park (BL-088) */
// activity = the larger of use and purchases in 60 days (items without a recipe show their use only through purchases); under 1,000 toman = no activity
// or no real price yet (fix the price first), not suggested; nothing is pre-ticked
function parkSuggest(){const {rows}=cycleData(),tot=rows.reduce((s,r)=>s+(r.activity||0),0),pk=parkedSet();return rows.filter(r=>r.cls==='C'&&!pk.has(r.id)&&tot>0&&r.activity>=1000&&r.activity<tot*0.002).sort((a,b)=>a.activity-b.activity)}
function parkForm(){const list=parkSuggest();if(!list.length)return P.toast('قلم کم‌ارزشی برای پیشنهاد نیست','info');
 formModal({title:'پیشنهاد کنارگذاشتن اقلام کم‌ارزش',size:'wide',ok:'ذخیره روی سرور',body:P.note(`${fa(list.length)} قلم گروه C که مصرف یا خرید ۶۰ روزشان (هر کدام بیشتر) کمتر از ۰٫۲٪ کل است؛ اقلام بی‌گردش یا بی‌قیمت پیشنهاد نمی‌شوند. هر کدام را می‌خواهید تیک بزنید. تیک‌خورده‌ها «کنارگذاشته» می‌شوند: در شمارش آخر فهرست می‌آیند و مغایرتشان در جمع مغایرت و افت حساب نمی‌شود (جدا نشان داده می‌شود). هر وقت بخواهید در «تنظیمات انبار ← سطح کنترل» برمی‌گردند.`,'info')+`<button type="button" class="btn btn-ghost btn-sm" onclick="this.closest('.modal').querySelectorAll('[data-pk]').forEach(x=>x.checked=true)">انتخاب همه</button><div style="max-height:52vh;overflow:auto">${P.table(['',{t:'کالا'},{t:'گروه'},{t:'مصرف یا خرید ۶۰ روز',m:1}],list.map(r=>[`<input type="checkbox" data-pk="${esc(r.id)}">`,esc(r.i?.name||r.id),esc(r.i?.category||''),P.mt(Math.round(r.activity))]),{cls:'no-grid'})}</div>`,
  onSave:(m,btn)=>{const levels={};for(const x of m.querySelectorAll('[data-pk]'))if(x.checked)levels[x.dataset.pk]='PARKED';if(!Object.keys(levels).length)throw Error('قلمی انتخاب نشده است');run(btn,{action:'ITEM_CONTROL_LEVELS_CHANGED',details:{source:'park-suggestion'},ioOpts:{recalc:false},mutate:(d,c)=>W.saveControlLevels(d,c,{levels}),done:o=>`${fa(o.changes)} قلم کنارگذاشته شد`})}})}
function cycleReal(){const {set,rows}=cycleData(),due=rows.filter(r=>r.due),c=(k,d)=>rows.filter(r=>r.cls===k&&(!d||r.due)).length,list=(cyF==='a'?due.filter(r=>r.cls==='A'):cyF==='ab'?due.filter(r=>r.cls!=='C'):cyF==='due'?due:rows).sort((x,y)=>x.cls.localeCompare(y.cls)||y.over-x.over||y.value-x.value),ed=canVoid()||P.owner();
 const inp=(k,l)=>P.field(l,`<input class="input num" data-cy="${k}" value="${fa(set[k])}" ${ed?'':'disabled'}>`);
 return srcLine()+`<div class="grid grid-4">${['A','B','C'].map(k=>P.kpi({label:'گروه '+k,icon:k==='A'?'gem':k==='B'?'box':'package',value:`${fa(c(k,1))} <small class="muted">از ${fa(c(k))}</small>`,foot:`موعد شمارش · هر ${fa(set[k.toLowerCase()])} روز`})).join('')}${P.kpi({label:'فهرست امروز',icon:'clipboard-check',value:fa(list.filter(r=>r.due).length),foot:'قلم در فهرست انتخاب‌شده'})}</div>
  <div class="row mt" style="gap:8px;flex-wrap:wrap;align-items:center">${P.chips('cy',[['a','موعد A',c('A',1)],['ab','موعد A و B',c('A',1)+c('B',1)],['due','همهٔ موعدها',due.length],['all','همهٔ اقلام',rows.length]],cyF)}${canWrite()&&parkSuggest().length?`<button class="btn btn-ghost" id="cyPark">${P.ic('archive')}پیشنهاد کنارگذاشتن کم‌ارزش‌ها (${fa(parkSuggest().length)})</button>`:''}${canWrite()?`<button class="btn btn-primary" id="cyGo">${P.ic('clipboard-check')}شمارش اقلام همین فهرست</button>`:''}</div>
  <div class="mt">${P.card({flush:1,body:P.table(['گروه','کالا','گروه کالا',{t:'مصرف ۶۰ روز',m:1},'آخرین شمارش',{t:'روز گذشته',n:1,noSum:1},'وضعیت'],list.slice(0,400).map(r=>[P.b(r.cls,r.cls==='A'?'danger':r.cls==='B'?'warning':'neutral',1),esc(r.i?.name||r.id),esc(r.i?.category||''),r.value?P.mt(Math.round(r.value)):'—',r.last?fa(r.last):'<span class="muted">هرگز</span>',r.age===null?'—':fa(r.age),r.due?P.b('موعد شمارش','warning',1):P.b('به‌روز','success',1)]),{empty:'در این فهرست قلمی موعد شمارش ندارد'})})}</div>
  <div class="mt">${P.card({title:'تنظیم شمارش چرخه‌ای و پیشنهاد نقطهٔ سفارش',sub:'گروه A = اقلامی که با هم این درصد از ارزش مصرف ۶۰ روز را می‌سازند؛ B تا درصد دوم؛ بقیه C. فاصله‌ها به روز.',body:`<div class="form-grid">${inp('a','فاصلهٔ A')}${inp('b','فاصلهٔ B')}${inp('c','فاصلهٔ C')}${inp('aShare','سهم A (٪)')}${inp('bShare','سهم A+B (٪)')}${inp('lead','روز تحویل تأمین‌کننده')}${inp('safety','روز ذخیرهٔ اطمینان')}${inp('cycle','فاصلهٔ سفارش (روز)')}</div>${ed?`<button class="btn btn-primary btn-sm mt" id="cySave">${P.ic('check')}ذخیرهٔ تنظیم</button>`:''}<p class="muted" style="font-size:12px">شمارش کامل آخر ماه به جای خودش می‌ماند؛ شمارش چرخه‌ای فقط اقلام موعددار را می‌خواهد و بقیه از شمارش قبلی خودشان ادامه می‌دهند.</p>`})}</div>`}
function cycleMount(root){{const pb=P.$('#cyPark',root);if(pb)pb.onclick=parkForm}P.bindChips(root,'cy',k=>{cyF=k;P.render()});const go=P.$('#cyGo',root);if(go)go.onclick=()=>{const {rows}=cycleData(),ids=(cyF==='a'?rows.filter(r=>r.due&&r.cls==='A'):cyF==='ab'?rows.filter(r=>r.due&&r.cls!=='C'):cyF==='due'?rows.filter(r=>r.due):rows).map(r=>r.id);if(!ids.length)return P.toast('قلمی در فهرست نیست','info');countForm({only:ids,title:`شمارش چرخه‌ای امروز (${fa(ids.length)} قلم)`})};
 const sv=P.$('#cySave',root);if(sv)sv.onclick=()=>{const input={};for(const el of root.querySelectorAll('[data-cy]'))input[el.dataset.cy]=latin(el.value);run(sv,{action:'CYCLE_COUNT_SETTINGS_SAVED',ioOpts:{recalc:false},mutate:(d,c)=>W.saveCycleSettings(d,c,input),done:()=>'تنظیم شمارش چرخه‌ای ذخیره شد'})}}

/* ---------- suggested reorder points from use (APP_REVIEW P-18) ----------
   Daily use of the last 28 days (recipe use of sales scaled up by the share of days with a sales file, + waste + staff
   use) × the lead / safety / order-cycle days of «شمارش امروز ← تنظیم». Items without a reorder point are pre-ticked. */
function reorderSuggest(){const set=W.cycleSettings(raw().inventory),t=E.CAL.today,days=28;let a=null;try{a=E.analyze(M(),E.CAL.k(E.CAL.i(t)-days+1),t)}catch(e){return P.toast('تحلیل مصرف انجام نشد','alert-triangle')}
 const cov=a.coverage>0.2?a.coverage:1,cur=new Map(pos().map(r=>[r.id,r])),rows=A(a.items).map(r=>{const d=((r.sales||0)/cov+(r.waste||0)+(r.staff||0))/days,sg=W.suggestReorder(d,set),c=cur.get(r.id);return sg&&c?{id:r.id,name:r.name,unit:r.unit,daily:d,sg,rp:c.hasReorderPoint&&c.reorderPoint>0?c.reorderPoint:null,tg:c.hasReorderPoint&&c.reorderPoint>0?c.target:null}:null}).filter(Boolean).sort((x,y)=>(x.rp===null?0:1)-(y.rp===null?0:1)||y.daily-x.daily);
 formModal({title:'پیشنهاد نقطهٔ سفارش از مصرف',size:'wide',ok:'ذخیرهٔ اقلام تیک‌خورده',body:`<p class="muted" style="margin-top:0">مصرف روزانهٔ ${fa(days)} روز اخیر × (${fa(set.lead)} روز تحویل + ${fa(set.safety)} روز اطمینان)؛ هدف = نقطهٔ سفارش + مصرف ${fa(set.cycle)} روز. ${a.coverage<0.999?`فروش فقط ${fa(Math.round(a.coverage*100))}٪ روزها وارد شده و مصرف فروش به همان نسبت بزرگ شده است.`:''} قبل از ذخیره اعداد را بازبینی کنید.</p>
   <div class="row" style="gap:8px;margin-bottom:8px"><label class="check"><input type="checkbox" id="rsAll">همه</label><span class="muted" id="rsN"></span></div>
   ${P.table([{t:'',noSort:1,noSum:1},'کالا',{t:'مصرف روزانه',n:1,noSum:1},{t:'نقطهٔ سفارش فعلی',n:1,noSum:1},{t:'هدف فعلی',n:1,noSum:1},{t:'نقطهٔ سفارش پیشنهادی',noSum:1},{t:'هدف پیشنهادی',noSum:1}],rows.map(r=>({attr:`data-rs="${esc(r.id)}"`,c:[`<input type="checkbox" class="check" ${r.rp===null?'checked':''}>`,esc(r.name),`${q(r.daily,3)} <small class="muted">${esc(r.unit)}</small>`,r.rp===null?'—':q(r.rp,2),r.tg===null?'—':q(r.tg,2),`<input class="input num sm" style="width:90px" data-v="rp" value="${fa(r.sg.reorderPoint)}">`,`<input class="input num sm" style="width:90px" data-v="tg" value="${fa(r.sg.targetStock)}">`]})),{cls:'no-grid',empty:'مصرفی در ۲۸ روز اخیر نیست'})}`,
  onMount:m=>{const cnt=()=>{P.$('#rsN',m).textContent=`${fa(m.querySelectorAll('[data-rs] input[type=checkbox]:checked').length)} قلم انتخاب شده`};cnt();m.addEventListener('change',cnt);P.$('#rsAll',m).onchange=e=>{m.querySelectorAll('[data-rs] input[type=checkbox]').forEach(c=>c.checked=e.target.checked);cnt()}},
  onSave:(m,btn)=>{const out={};for(const tr of m.querySelectorAll('[data-rs]')){if(!tr.querySelector('input[type=checkbox]').checked)continue;out[tr.dataset.rs]={reorderPoint:latin(tr.querySelector('[data-v=rp]').value),targetStock:latin(tr.querySelector('[data-v=tg]').value)}}if(!Object.keys(out).length)throw Error('قلمی انتخاب نشده است');
   run(btn,{action:'REORDER_POINTS_CHANGED',details:{source:'suggestion'},io:ioPricing,apply:doc=>IC.attach({...raw(),pricing:doc,source:'live'}),mutate:(d,c)=>W.saveReorderPoints(d,c,{rows:out}),done:n=>`نقطهٔ سفارش ${fa(n)} قلم ذخیره شد`})}})}

function catalogReal(){const m=M(),rows=[...m.ing.values()].sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));
 return srcLine()+P.card({title:'کاتالوگ کالاها و مواد',sub:'مرجع اصلی (pricing.ingredients)',flush:1,body:P.table(['کد','نام','گروه','نوع','واحد مصرف','واحد خرید',{t:'مقدار بسته',n:1},{t:'آخرین قیمت خرید',m:1},'وضعیت'],rows.slice(0,700).map(i=>[esc(i.code),esc(i.name),esc(i.category),esc(i.itemType||''),esc(i.recipeUnit),esc(i.purchaseUnit),q(Number(i.packageQuantity),3),Number(i.lastPurchasePriceToman)>1?P.mt(Number(i.lastPurchasePriceToman)):P.b('بدون قیمت','warning'),i.status==='غیرفعال'?P.b('غیرفعال','neutral'):P.b('فعال','success')]))})}

/* ---------- entry forms (stage 2) ---------- */
const raw=()=>IC.state.raw;
const io={
 load:async()=>{const r=await fetch(E.API_ROOT+'Load?module=inventory&_='+Date.now(),{cache:'no-store',credentials:'omit',headers:{Accept:'application/json'}});if(!r.ok)throw Error(`دریافت انبار از سرور: HTTP ${r.status}`);return E.unwrap(await r.json())},
 save:async doc=>{const r=await fetch(E.API_ROOT+'Save?module=inventory',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json; charset=utf-8',Accept:'application/json, text/plain, */*'},body:JSON.stringify(doc)});if(!r.ok)throw Error(`ذخیره روی سرور: HTTP ${r.status} ${(await r.text()).slice(0,200)}`)},
 actor:()=>ses('rayo_admin_user'),pricing:()=>raw().pricing};
// shared by menu-real.js: io (module) and apply(doc) default to the inventory module
/* ---------- negative stock at the moment of entry (APP_REVIEW P-17) ----------
   The entry is applied to a copy of the current data; items whose computed stock today goes below zero (or further
   below) are listed in the form with the likely causes. The save is not blocked: a second click saves anyway (the
   invoice may simply not have arrived yet, or past months are being entered out of order). */
function lastReceiptOf(id){let d='';for(const x of M().receipts)if(x.item===id&&x.date>d)d=x.date;return d}
function negativeAfter(mutate){const r=raw(),doc=JSON.parse(JSON.stringify(r.inventory)),ctx={actor:'check',at:new Date().toISOString(),reqId:'NEGCHECK',pricing:r.pricing,module:'inventory'};mutate(doc,ctx);
 const after=new Map(E.positions(E.build({...r,inventory:doc}),E.CAL.today).map(x=>[x.id,x]));
 return pos().map(b=>({b,a:after.get(b.id)})).filter(({b,a})=>a&&a.qty!==null&&a.qty<-1e-9&&a.qty<(b.qty??0)-1e-9).map(({b,a})=>({id:b.id,name:b.name,unit:b.unit,before:b.qty,after:a.qty,last:lastReceiptOf(b.id),base:b.basePt?.date||''}))}
function negHtml(neg,lead){return P.note(`<b>${lead}</b><ul style="margin:6px 0;padding-inline-start:18px">${neg.slice(0,12).map(n=>`<li><b>${esc(n.name)}</b>: ${q(n.before,3)} ← <b class="neg">${q(n.after,3)}</b> ${esc(n.unit)} <small class="muted">(آخرین ورود: ${n.last?fa(n.last):'ندارد'}${n.base?' · آخرین شمارش: '+fa(n.base):''})</small></li>`).join('')}${neg.length>12?`<li>و ${fa(neg.length-12)} قلم دیگر</li>`:''}</ul>احتمالاً: فاکتور یا ورود کالای اخیر ثبت نشده؛ مقدار یا واحد همین ثبت اشتباه است (گرم به‌جای کیلو)؛ یا شمارش قبلی کم بوده است.`,'alert-triangle')}
function showNeg(btn,neg){const md=btn.closest('.modal');if(!md)return;let box=md.querySelector('#iwNeg');if(!box){box=document.createElement('div');box.id='iwNeg';const er=md.querySelector('#iwErr');(er?.parentNode||md.querySelector('.modal-body')).insertBefore(box,er||null)}
 box.innerHTML=negHtml(neg,`با این ثبت ${fa(neg.length)} قلم موجودی منفی پیدا می‌کنند:`);btn.dataset.negOk='1';btn.dataset.lbl=btn.dataset.lbl||btn.innerHTML;btn.innerHTML=P.ic('alert-triangle')+'با این حال ذخیره شود';RT.icons();box.scrollIntoView({block:'nearest'});
 const reset=()=>{delete btn.dataset.negOk;box.innerHTML='';if(btn.dataset.lbl){btn.innerHTML=btn.dataset.lbl;RT.icons()}};md.addEventListener('input',reset,{once:true});md.addEventListener('change',reset,{once:true})}
async function run(btn,{action,details,mutate,done,then,io:mio=io,ioOpts,negWarn,apply=doc=>IC.attach({...raw(),inventory:doc,source:'live'})}){
 if(negWarn&&btn.dataset.negOk!=='1'){let neg=[];try{neg=negativeAfter(mutate)}catch(_){}if(neg.length)return showNeg(btn,neg)}
 delete btn.dataset.negOk;const label=btn.innerHTML;btn.disabled=true;btn.innerHTML=P.ic('loader')+'ذخیره و تأیید روی سرور…';RT.icons();
 try{const {out,doc}=await W.edit(ioOpts?{...mio,...ioOpts}:mio,{action,details,mutate});apply(doc);P.close();P.render();P.toast(done(out)+(out&&out.recalculated?` — مغایرت ${fa(out.recalculated)} ردیف در شمارش‌های بعدی بازمحاسبه شد`:''),'check');if(then)setTimeout(()=>then(out),80)}
 catch(e){const el=document.getElementById('iwErr');if(el)el.textContent=e.message||String(e);P.toast(e.message||String(e),'alert-triangle');if(W.state.uncertain){P.close();P.render()}}
 finally{if(document.body.contains(btn)){btn.disabled=false;btn.innerHTML=label;RT.icons()}}}
function formModal({title,body,ok='ذخیره',size='',onMount,onSave,can=canWrite,why=whyLocked,again=''}){
 P.modal({title,size,body:`<form id="iwForm" class="stack" style="gap:var(--s4)" onsubmit="return false">${body}<div id="iwErr" class="neg" role="alert" style="font-size:13px"></div></form>`,
  foot:`<button class="btn btn-ghost" data-close>انصراف</button>${again?`<button class="btn btn-secondary" id="iwAgain">${P.ic('copy-plus')}${again}</button>`:''}<button class="btn btn-primary" id="iwOk">${P.ic('check')}${ok}</button>`,
  onMount:m=>{onMount&&onMount(m);const go=(b,next)=>e=>{e.preventDefault();P.$('#iwErr',m).textContent='';if(!can())return P.$('#iwErr',m).textContent=why();try{onSave(m,b,next)}catch(err){P.$('#iwErr',m).textContent=err.message}};P.$('#iwOk',m).onclick=go(P.$('#iwOk',m),false);const a=P.$('#iwAgain',m);if(a)a.onclick=go(a,true)}})}
const val=(m,n)=>P.$(`[name=${n}]`,m)?.value??'';
const dateField=(label='تاریخ')=>P.field(label,`<input class="input num" name="date" value="${fa(E.CAL.today)}" placeholder="۱۴۰۵/۰۸/۱۷">`);
const shiftField=()=>P.field('شیفت',`<select class="select" name="shift">${W.SHIFTS.map(s=>`<option>${s}</option>`).join('')}</select>`);
const itemLabel=i=>`${i.name}${i.code?' — '+i.code:''}`;
const stockList=()=>[...M().ing.values()].filter(W.stockItem).sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));
const menuList=()=>[...M().menu.values()].filter(x=>x.status!=='غیرفعال').sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));
const dataList=(id,list)=>`<datalist id="${id}">${list.map(i=>`<option value="${esc(itemLabel(i))}"></option>`).join('')}</datalist>`;
const latin=s=>String(s).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const pick=(v,list)=>{v=String(v||'').trim();return list.find(i=>itemLabel(i)===v)||list.find(i=>i.name===v)||list.find(i=>i.code&&String(i.code)===latin(v))||window.PurchaseWrite?.mergedPick?.(raw().pricing,v,list)||null};
// unit options of an item; sel = the unit selected first (count unit, use unit, purchase unit…)
const unitOpts=(i,sel)=>i?W.unitsOf(i).map(u=>`<option value="${esc(u.name)}" ${u.name===sel?'selected':''}>${esc(u.name)}${u.factor!==1?` (${fa(+u.factor.toFixed(6))} ${esc(W.unitName(i))})`:''}</option>`).join(''):'';

function receiptForm(){const list=stockList(),row=()=>`<div class="iw-row"><input class="input" list="iwItems" data-f="item" placeholder="نام یا کد کالا" aria-label="کالا"><input class="input num" data-f="qty" inputmode="decimal" placeholder="مقدار" aria-label="مقدار"><select class="select" data-f="unit" aria-label="واحد"></select><input class="input" data-f="note" placeholder="توضیح (اختیاری)" aria-label="توضیح"><button type="button" class="btn btn-ghost btn-sm btn-icon" data-del aria-label="حذف ردیف">${P.ic('x')}</button></div>`;
 formModal({title:'ثبت ورود به انبار',size:'wide',ok:'ذخیره روی سرور',body:`${dataList('iwItems',list)}<div class="form-grid">${dateField('تاریخ ورود')}</div><div id="iwRows" class="stack" style="gap:8px">${row()}${row()}${row()}</div><button type="button" class="btn btn-ghost btn-sm" id="iwAdd" style="align-self:flex-start">${P.ic('plus')}ردیف جدید</button>${P.note('ورود بدون قیمت ثبت می‌شود، مثل «ورود به انبار» پنل فعلی. قیمت خرید از فاکتور و قیمت‌گذاری می‌آید. مقدار به واحد خرید (مثلاً کارتن) خودکار به واحد انبار تبدیل می‌شود.','info')}`,
  onMount:m=>{const rows=P.$('#iwRows',m);P.$('#iwAdd',m).onclick=()=>{rows.insertAdjacentHTML('beforeend',row());RT.icons()};rows.addEventListener('click',e=>{const b=e.target.closest('[data-del]');if(b&&rows.children.length>1)b.closest('.iw-row').remove()});rows.addEventListener('change',e=>{if(e.target.dataset.f==='item'){const x=pick(e.target.value,list);e.target.closest('.iw-row').querySelector('[data-f=unit]').innerHTML=x?unitOpts(x,(W.unitsOf(x).find(u=>u.purchase)||W.unitsOf(x)[0]).name):''}})},
  onSave:(m,btn)=>{const date=E.D(val(m,'date')),lines=[...m.querySelectorAll('.iw-row')].map(r=>({v:r.querySelector('[data-f=item]').value.trim(),q:r.querySelector('[data-f=qty]').value.trim(),u:r.querySelector('[data-f=unit]').value,n:r.querySelector('[data-f=note]').value})).filter(x=>x.v||x.q).map((x,k)=>{const i=pick(x.v,list);if(!i)throw Error(`ردیف ${fa(k+1)}: کالا را از فهرست انتخاب کنید`);return{itemId:i.id,quantity:x.q,unit:x.u,note:x.n}});
   if(!lines.length)throw Error('حداقل یک ردیف وارد کنید');const warn=W.receiptWarnings(raw().inventory,raw().pricing,date,W.receiptLines(raw().pricing,lines));if(warn.length&&!confirm(warn.join('\n')+'\n\nبا همین مقادیر ذخیره شود؟'))return;
   run(btn,{action:'RECEIPT_BATCH_ADDED',details:{date,lines:lines.length},mutate:(d,c)=>W.addReceipts(d,c,{date,lines}),done:o=>`${fa(o.count)} ورود ثبت و روی سرور تأیید شد`})}})}

/* waste / authorized use; «ذخیره و ثبت بعدی» keeps date, type, kind and shift and opens an empty form again */
/* ---------- waste: section (بخش) and responsible person, from the personnel module ----------
   section list = personnel lists.sections; an old record without «section» shows the section of its inventory location
   (when not the main warehouse) or of its responsible person. A fine from a waste record is a penalty with source «waste». */
const HR=()=>{const PR=window.PeopleReal;if(PR&&!PR.doc()&&!PR.state?.err&&!PR.state?.busy)PR.load();return PR?.doc?.()||null};
const staffAll=()=>A(HR()?.personnel);
const personOf=id=>staffAll().find(p=>p.id===id)||null;
const personSection=p=>String(p?.section||p?.personnelGroup||'').trim();
const wasteSections=()=>{const l=A(HR()?.lists?.sections).map(x=>String(x).trim()).filter(Boolean);if(l.length)return l;return [...new Set(A(raw().inventory?.locations).filter(x=>x.type!=='main').map(x=>String(x.section||x.name||'').trim()).filter(Boolean))]};
const recSection=r=>{if(!r)return'';if(r.section)return r.section;const loc=A(raw().inventory?.locations).find(l=>l.id===r.locationId);if(loc&&loc.type!=='main'&&(loc.section||loc.name))return String(loc.section||loc.name);return personSection(personOf(r.responsiblePersonnelId))};
const recPerson=r=>r?.responsiblePersonnelId?(personOf(r.responsiblePersonnelId)?.name||r.responsibleNameSnapshot||r.responsiblePersonnelId):'';
const fineOf=id=>A(HR()?.penaltiesRewards).find(x=>x.source==='waste'&&x.sourceId===id&&x.status!=='لغوشده')||null;
const sectionOpts=sel=>{const l=wasteSections();if(sel&&!l.includes(sel))l.push(sel);return '<option value="">انتخاب بخش</option>'+l.map(x=>`<option ${x===sel?'selected':''}>${esc(x)}</option>`).join('')};
const personOptsW=sel=>'<option value="">— نامشخص —</option>'+staffAll().filter(p=>p.status==='فعال'||p.id===sel).sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa')).map(p=>`<option value="${esc(p.id)}" data-sec="${esc(personSection(p))}" ${p.id===sel?'selected':''}>${esc(p.name)}${personSection(p)?' — '+esc(personSection(p)):''}</option>`).join('');
const sectionFields=(sec='',pid='')=>`<div class="form-grid">${P.field('بخش *',`<select class="select" name="section">${sectionOpts(sec)}</select>`,'پرتی از کدام بخش است')}${P.field('فرد مسئول',`<select class="select" name="person">${personOptsW(pid)}</select>`,HR()?'بخش از روی بخش همین فرد پر می‌شود':'فهرست پرسنل در حال خواندن است…')}</div>`;
// choosing a person fills the section when it is empty (or matches the section the list knows for that person)
