 const L=cl?cl.stocktakeLines.map(x=>({...x,wq:x.wasteQty})):r.lines.map(l=>{const v=W.reviewOf(doc,date,l.ingredientId);return{ingredientId:l.ingredientId,name:nmL(l),code:l.itemCodeSnapshot||'',unit:l.unitSnapshot||'',baseDate:l.baseDate,baseQuantity:l.baseQuantity,purchaseQty:l.purchaseQty,salesConsumption:l.salesConsumption,wq:(Number(l.wasteQty)||0)+(Number(l.otherOutQty)||0),expected:l.expected,actual:l.actual,variance:l.variance,varianceValueToman:Number(l.varianceValueToman)||0,review:v?.status,reviewNote:v?.note}});
