 const row=x=>`<tr><td>${esc(x.name)}${x.code?` <small>${esc(x.code)}</small>`:''}</td><td>${esc(x.unit)}</td><td>${x.baseDate?fa(x.baseDate):'—'}</td><td class="n">${n(x.baseQuantity)}</td><td class="n">${n(x.purchaseQty)}</td><td class="n">${n(x.salesConsumption)}</td><td class="n">${n(x.wq)}</td><td class="n">${n(x.expected)}</td><td class="n">${n(x.actual)}</td><td class="n ${Number(x.variance)<0?'neg':''}">${n(x.variance)}</td><td class="n ${x.varianceValueToman<0?'neg':''}">${t(x.varianceValueToman)}</td><td>${x.review?esc(W.REVIEW_LABELS[x.review]||x.review)+(x.reviewNote?`<small>${esc(x.reviewNote)}</small>`:''):''}</td></tr>`;
